	private static final IRI CATEGORY = VF.createIRI(NS + "category");
	private static final IRI KNOWS = VF.createIRI(NS + "knows");
	private static final IRI RARE = VF.createIRI(NS + "rare");
	private static final String PREFIX = "PREFIX ex: <" + NS + "> ";
	private static final int PEOPLE = 600;
	private static final String NONCE_PROPERTY = "rdf4j.optimizer.revalidationSoundnessNonce";
