	private final Map<String, String> previousProperties = new LinkedHashMap<>();

	@AfterEach
	void restoreProperties() {
		previousProperties.forEach((name, previous) -> {
			if (previous == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, previous);
			}
		});
	}

	@ParameterizedTest(name = "profile={0} sampling={1} audit={2}")
	@CsvSource({ "default,false,false", "default,true,false", "safe-plan-lifecycle,true,false",
			"experimental-full,true,false", "safe-plan-lifecycle,false,false", "default,true,true",
			"experimental-full,false,true" })
	void everyRevalidatedServeEqualsAnIndependentFreshPlanning(String profile, boolean sampling, boolean audit,
			@TempDir Path directory) throws Exception {
		if (!"default".equals(profile)) {
			setProperty("rdf4j.optimizer.lmdb.leoProfile", profile);
		}
		setProperty(LmdbPlanCacheRevalidation.AUDIT_PROPERTY, Boolean.toString(audit));
		// Keep every log (the default cap drops large ones): more variants are revalidatable.
		setProperty(LmdbPlanCacheRevalidation.MAX_BYTES_PROPERTY, Long.toString(64L << 20));
		List<String> mismatches = new ArrayList<>();
		Map<String, Long> reasons = new LinkedHashMap<>();
		long revalidated = 0L;
		long compared = 0L;
		long freshMissed = 0L;
		long freshPackedHits = 0L;
		long withinToleranceDifferences = 0L;
		try (Fixture fixture = new Fixture(directory, sampling)) {
			for (int round = 0; round < 10; round++) {
				for (Map.Entry<String, String> query : WORKLOAD.entrySet()) {
					List<String> bindings = "boundCat".equals(query.getKey()) ? List.of("c1", "c3") : List.of("");
					for (String binding : bindings) {
						String label = query.getKey() + (binding.isEmpty() ? "" : "[" + binding + "]");
						TupleExpr served = fixture.explain(query.getValue(), binding);
						String reason = served.getStringMetricPlanned("optimizer.planCacheRefreshReason");
						reasons.merge(String.valueOf(reason), 1L, Long::sum);
						if (LmdbPlanCacheRevalidation.REVALIDATED.equals(reason)
								|| LmdbPlanCacheRevalidation.REVALIDATED_WITHIN_TOLERANCE.equals(reason)) {
							revalidated++;
							long leoBefore = fixture.runtime.capturePlanningRevisions().leoRevision();
							TupleExpr fresh = fixture.explainFresh(query.getValue(), binding);
							long leoAfter = fixture.runtime.capturePlanningRevisions().leoRevision();
							if (fresh.getStringMetricPlanned("optimizer.planCacheLookupOutcome") != null) {
								freshMissed++;
							}
							if ("true".equals(packedHit(fresh))) {
								freshPackedHits++;
							}
							compared++;
							String servedSignature = signature(served);
							String freshSignature = signature(fresh);
							if (!servedSignature.equals(freshSignature)
									&& LmdbPlanCacheRevalidation.REVALIDATED_WITHIN_TOLERANCE.equals(reason)) {
								// F9 (B0 as amended): after a within-tolerance revalidation a different fresh plan is
								// measured, not a defect.
								withinToleranceDifferences++;
							} else if (!servedSignature.equals(freshSignature)) {
								mismatches.add("round=" + round + " query=" + label + " reason=" + reason
										+ " leoMovedDuringFresh=" + (leoBefore != leoAfter) + "\n  served="
										+ servedSignature
										+ "\n  fresh =" + freshSignature + "\n  servedPlan=\n" + served
										+ "\n  freshPlan=\n"
										+ fresh);
							}
						}
						fixture.evaluate(query.getValue(), binding);
					}
				}
				fixture.settle();
			}
			LmdbPlanCacheRevalidation.Snapshot counters = fixture.revalidation();
			System.out.println("[revalidation-soundness] profile=" + profile + " sampling=" + sampling + " audit="
					+ audit
					+ " revalidated=" + revalidated + " compared=" + compared + " freshNotAMiss=" + freshMissed
					+ " freshPackedHits=" + freshPackedHits + " withinToleranceDifferences="
					+ withinToleranceDifferences
					+ " mismatches=" + mismatches.size() + "\n  counters=" + counters + "\n  reasons=" + reasons);
			for (String mismatch : mismatches) {
				System.out.println("[revalidation-soundness][MISMATCH] " + mismatch);
			}
			assertTrue(revalidated > 0L, "COVERAGE_PREREQUISITE: revalidated serves happened: " + reasons);
			assertEquals(0L, counters.auditMismatches(), "audit mismatches: " + counters);
			assertEquals(List.of(), mismatches);
			// F3: the audit's own planning neither reads nor publishes the packed plan cache, so a later planning at
			// the same revision is a full search, never a hit on an entry the audit left behind.
			assertEquals(0L, freshPackedHits, "fresh plannings served by a packed entry: " + counters);
		}
	}

	/** The packed plan cache hit flag the cascades optimizer stamps on the planned root (or its argument). */
	static String packedHit(TupleExpr plan) {
		String hit = plan.getStringMetricPlanned(LmdbCascadesOptimizer.PLAN_CACHE_HIT_METRIC);
		if (hit == null && plan instanceof org.eclipse.rdf4j.query.algebra.QueryRoot root) {
			hit = root.getArg().getStringMetricPlanned(LmdbCascadesOptimizer.PLAN_CACHE_HIT_METRIC);
		}
		return hit;
	}

	/** Operators in visit order with algorithms, statement-pattern variables (anonymous ones blanked) and indexes. */
	static String signature(TupleExpr plan) {
		StringBuilder signature = new StringBuilder(512);
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				signature.append('(').append(node.getClass().getSimpleName());
				if (node instanceof BinaryTupleOperator operator && operator.getAlgorithmName() != null) {
					signature.append(':').append(operator.getAlgorithmName());
				}
				if (node instanceof StatementPattern pattern) {
					signature.append(':').append(pattern.getScope()).append(':').append(pattern.getIndexName());
					for (Var var : pattern.getVarList()) {
						signature.append(':')
								.append(var.hasValue() ? var.getValue().stringValue()
										: var.isAnonymous() || var.getName().startsWith("_") ? "_"
												: "?" + var.getName());
					}
				}
				super.meetNode(node);
				signature.append(')');
			}
		});
		return signature.toString();
	}

	private void setProperty(String name, String value) {
		// Not putIfAbsent: a property that was unset is remembered as null, which putIfAbsent would overwrite.
		if (!previousProperties.containsKey(name)) {
			previousProperties.put(name, System.getProperty(name));
		}
		System.setProperty(name, value);
	}

	private static final class Fixture implements AutoCloseable {
		private final LmdbStore store;
		private final SailRepository repository;
		private final SailRepositoryConnection connection;
		private final LmdbEstimatorRuntime runtime;

		Fixture(Path directory, boolean liveSampling) throws Exception {
			LmdbStoreConfig config = new LmdbStoreConfig();
			config.setOptimizerSamplingEnabled(liveSampling);
			config.setOptimizerSamplingMaxMillis(2_000L);
			// A pipeline budget (1/16 of this) that holds the whole workload with its logs: revalidation, not
			// capacity, decides the outcome of a lookup.
			config.setFrontierCacheEvidenceBudgetBytes(2L << 30);
			store = new LmdbStore(directory.toFile(), config);
			repository = new SailRepository(store);
			repository.init();
			connection = repository.getConnection();
			connection.begin();
			for (int index = 0; index < PEOPLE; index++) {
				IRI person = VF.createIRI(NS + "person/" + index);
				connection.add(person, NAME, VF.createLiteral("Person " + index));
				connection.add(person, AGE, VF.createLiteral(index % 100));
				// Skewed categories: half of everyone is c0.
				connection.add(person, CATEGORY, VF.createLiteral(index % 2 == 0 ? "c0" : "c" + index % 7));
				connection.add(person, KNOWS, VF.createIRI(NS + "person/" + (index + 1) % PEOPLE));
				connection.add(person, KNOWS, VF.createIRI(NS + "person/" + index * 7 % PEOPLE));
				if (index % 3 == 0) {
					// A hub everyone-third knows.
					connection.add(person, KNOWS, VF.createIRI(NS + "person/0"));
				}
				if (index % 97 == 0) {
					connection.add(person, RARE, VF.createLiteral(index));
				}
			}
			connection.commit();
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			settle();
			runtime = ((LmdbEvaluationStatistics) store.getSailStore().getEvaluationStatistics()).estimatorRuntime();
		}

		void settle() throws Exception {
			LmdbTestUtil.awaitBackgroundMaintenance(store, 120, TimeUnit.SECONDS);
		}

		TupleQuery prepare(String query, String binding) {
			TupleQuery prepared = connection.prepareTupleQuery(PREFIX + query);
			if (!binding.isEmpty()) {
				prepared.setBinding("c", VF.createLiteral(binding));
			}
			return prepared;
		}

		TupleExpr explain(String query, String binding) {
			return (TupleExpr) prepare(query, binding).explain(Explanation.Level.Optimized).tupleExpr();
		}

		/** A planning that misses the pipeline cache: its configuration differs in an unused optimizer property. */
		TupleExpr explainFresh(String query, String binding) {
			String previous = System.getProperty(NONCE_PROPERTY);
			System.setProperty(NONCE_PROPERTY, Long.toString(NONCE.incrementAndGet()));
			try {
				return explain(query, binding);
			} finally {
				if (previous == null) {
					System.clearProperty(NONCE_PROPERTY);
				} else {
					System.setProperty(NONCE_PROPERTY, previous);
				}
			}
		}

		long evaluate(String query, String binding) {
			long rows = 0L;
			try (TupleQueryResult result = prepare(query, binding).evaluate()) {
				while (result.hasNext()) {
					result.next();
					rows++;
				}
			}
			return rows;
		}

		LmdbPlanCacheRevalidation.Snapshot revalidation() {
			return runtime.frontierSettings().pipelinePlanCache().decisionCacheForTest().statistics().revalidation();
		}

		@Override
		public void close() {
			try {
				connection.close();
			} finally {
				repository.shutDown();
			}
		}
	}
